param([Parameter(Mandatory=$true)][string]$RunId)
$ErrorActionPreference='Stop'
# Local/background jobs use UUID hex; admitted platform turns use SHA-256.
# Keep command identities limited to the UUID form generated by Commands.
if($RunId -notmatch '^([0-9a-f]{32}|[0-9a-f]{64}|cmd-[0-9a-f]{32})$'){throw 'Execution identity required'}
$loomRoot=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$loomDirectory=Join-Path $loomRoot 'Control\DesktopHosts'
if($RunId.StartsWith('cmd-') -and (Test-Path -LiteralPath $loomDirectory)){[IO.File]::WriteAllText((Join-Path $loomDirectory ($RunId+'.stop')),'finished')}
foreach($loomName in @(('LOOM-Job-'+$RunId),('LOOM-Desktop-'+$RunId))){
    $loomDeadline=[DateTime]::UtcNow.AddSeconds(8)
    do {
        $loomTask=Get-ScheduledTask -TaskName $loomName -ErrorAction SilentlyContinue
        if(-not $loomTask -or $loomTask.State -ne 'Running'){break}
        Start-Sleep -Milliseconds 200
    } while([DateTime]::UtcNow -lt $loomDeadline)
    if($loomTask -and $loomTask.State -eq 'Running'){throw 'Execution task remains active; keep recovery pending'}
    if($loomTask){Unregister-ScheduledTask -TaskName $loomName -Confirm:$false}
}
$loomReceipt=Join-Path $loomDirectory ($RunId+'.json')
if(Test-Path -LiteralPath $loomReceipt){
    $loomResult=Get-Content -LiteralPath $loomReceipt -Raw | ConvertFrom-Json
    if($loomResult.id -ne $RunId -or -not $loomResult.desktop_closed -or -not $loomResult.station_closed){throw 'Desktop object cleanup not confirmed'}
}
